import {months,creditors,data,readPaid,summary,monthTotal,setMonth} from './debt-core.js?v=20261025a';
const fmt=n=>n.toLocaleString('en-US');
export function debtPage(storage){
 const {paid,error}=readPaid(storage),s=summary(paid);
 const colors=['#be185d','#6d28d9','#0369a1','#047857','#b45309'];
 const amount=n=>error?'—':fmt(n);
 return `<div class="debt-page">
 <div class="page-heading"><div><span class="eyebrow">พื้นที่ส่วนตัว · แผนเดิมของฉัน</span><h1>แผนจัดการหนี้</h1><p>ดูยอดผ่อนและติดตามการจ่าย ครบในแอปเรียนเดียวกัน</p></div><a class="button secondary" href="#home">← กลับหน้าการเรียน</a></div>
 <div class="debt-local" role="status"><strong>บันทึกในเครื่องนี้</strong><span>การติ๊กจ่ายแล้วเก็บในเบราว์เซอร์นี้ แยกจากข้อมูลเรียนออนไลน์ และไม่รวมในไฟล์สำรองการเรียน</span></div>
 ${error?`<div class="notice" role="alert">${error}</div>`:''}
 <section class="debt-hero"><div><span class="eyebrow">ยอดคงเหลือตามแผน</span><p class="debt-balance">${amount(s.left)} <small>บาท</small></p><p>แผนเดิม ส.ค.–มี.ค. · 8 เดือน · 5 เจ้าหนี้</p></div><div class="debt-next"><span>เดือนแรกที่ยังไม่ติ๊กจ่าย</span><strong>${error?'ยังอ่านข้อมูลไม่ได้':s.next?`${s.next} · ${fmt(monthTotal(s.next))} บาท`:'จ่ายครบตามแผนแล้ว ✓'}</strong><small>เรียงตามแผนเดิม ไม่ใช่การแจ้งยอดเรียกเก็บปัจจุบัน</small></div></section>
 <section class="debt-stats" aria-label="สรุปแผนหนี้"><div><span>ยอดรวมตามแผนเดิม</span><strong>${fmt(s.total)} <small>บาท</small></strong></div><div><span>จ่ายแล้วตามที่ติ๊ก</span><strong>${amount(s.paid)} <small>บาท</small></strong></div><div><span>เดือนที่จ่ายแล้ว</span><strong>${error?'—':s.count} <small>/ 8 เดือน</small></strong></div></section>
 <section class="panel debt-progress"><div><h2>ความคืบหน้าตามแผน</h2><b>${error?'—':s.percent+'%'}</b></div><progress max="100" ${error?'':`value="${s.percent}"`} aria-label="ความคืบหน้าการจ่าย"></progress><p>ยอดและเดือนคงไว้ตามแอปเดิม ยังไม่ได้ปรับตามยอดหนี้ปัจจุบัน</p></section>
 <section class="panel debt-schedule"><div class="section-heading"><div><h2>ตารางผ่อนรายเดือน</h2><p>กด “จ่ายแล้ว” เมื่อจ่ายครบทั้งเดือน · กดซ้ำเพื่อยกเลิก</p></div></div><div class="debt-table" tabindex="0" role="region" aria-label="ตารางผ่อนชำระ เลื่อนซ้ายขวาเพื่อดูครบทุกเจ้าหนี้"><table><caption class="sr-only">ตารางผ่อนตามแผนเดิมเดือนสิงหาคมถึงมีนาคม หน่วยบาท</caption><thead><tr><th scope="col">เดือน / สถานะ</th>${creditors.map(c=>`<th scope="col">${c.name}</th>`).join('')}<th scope="col">รวม (บาท)</th></tr></thead><tbody>${months.map(m=>`<tr class="${paid[m]?'debt-paid':''}"><th scope="row"><span>${m}</span><button class="debt-toggle" data-action="debt-toggle" data-month="${m}" aria-pressed="${!!paid[m]}" aria-label="จ่ายครบเดือน ${m}" ${error?'disabled':''}>${paid[m]?'✓ จ่ายแล้ว':'จ่ายแล้ว'}</button></th>${creditors.map(c=>{const v=data[m][c.key],last=months.filter(k=>data[k][c.key]>0).at(-1);return `<td>${v?fmt(v):'—'}${v&&last===m?'<small class="debt-close">ปิดตามแผน</small>':''}</td>`;}).join('')}<td><strong>${fmt(monthTotal(m))}</strong></td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">รวมทั้งหมด</th>${creditors.map(c=>`<td>${fmt(months.reduce((n,m)=>n+data[m][c.key],0))}</td>`).join('')}<td>${fmt(s.total)}</td></tr></tfoot></table></div><p class="debt-hint">เลื่อนตารางซ้าย–ขวาบนมือถือ · “ปิดตามแผน” คือเดือนสุดท้ายที่มีค่างวดในตารางเดิม</p></section>
 <section aria-labelledby="debt-creditors-title"><div class="section-heading"><h2 id="debt-creditors-title">แยกตามเจ้าหนี้</h2></div><div class="debt-creditors">${creditors.map((c,i)=>{const total=months.reduce((n,m)=>n+data[m][c.key],0),done=months.reduce((n,m)=>n+(paid[m]?data[m][c.key]:0),0);return `<article class="panel" style="--debt-color:${colors[i]}"><h3>${c.name}</h3><p>คงเหลือ <strong>${amount(total-done)} บาท</strong></p><progress max="${total}" ${error?'':`value="${done}"`} aria-label="การจ่าย ${c.name}"></progress><small>จ่ายแล้ว ${amount(done)} / ${fmt(total)} บาท</small></article>`;}).join('')}</div></section>
 </div>`;
}
export function debtAction(action,dataset,storage){return action==='debt-toggle'?setMonth(storage,dataset.month):'ไม่พบคำสั่ง';}
